    start = time.perf_counter()
    has_duplicate_slow(lst)
    elapsed = time.perf_counter() - start
    print(f"n={n:>6,}: {elapsed*1000:.2f} ms")

def binary_search(sorted_lst, target):   # O(log n)
    lo, hi = 0, len(sorted_lst) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if sorted_lst[mid] == target:
            return mid, steps
        elif sorted_lst[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps

for n in [1_000, 1_000_000, 1_000_000_000]:
    lst = list(range(n))
    _, steps = binary_search(lst, n - 1)
    print(f"n={n:>15,}: {steps} steps")

def fib_naive(n):        # O(2^n) -- recomputes the same subproblems repeatedly
    if n <= 1:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)

