def two_sum_sorted(sorted_lst, target):    # O(n) -- two pointers
    lo, hi = 0, len(sorted_lst) - 1
    while lo < hi:
        s = sorted_lst[lo] + sorted_lst[hi]
        if s == target:
            return (lo, hi)
        elif s < target:
            lo += 1          # need a bigger sum -> move left pointer up
        else:
            hi -= 1          # need a smaller sum -> move right pointer down
    return None

