def topo_sort(graph):
    visited = set()
    order = []
    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)
        order.append(node)
    for node in graph:
        if node not in visited:
            dfs(node)
    return order[::-1]

