def fib_naive(n):                  # O(2^n) -- the trap from Module 1
    if n <= 1:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)

def fib_memo(n, cache=None):       # O(n) -- top-down with memoization
    if cache is None:               # avoid the classic mutable-default-argument bug
        cache = {}
    if n <= 1:
        return n
    if n in cache:
        return cache[n]
    cache[n] = fib_memo(n - 1, cache) + fib_memo(n - 2, cache)
    return cache[n]

for n in [10, 20, 30]:
    assert fib_naive(n) == fib_memo(n)
