def climb_stairs(n):          # tabulation -- O(n) time, O(1) space
    if n <= 2:
        return n
    prev2, prev1 = 1, 2        # ways to reach step 1, step 2
    for step in range(3, n + 1):
        prev2, prev1 = prev1, prev1 + prev2
    return prev1

